-- NCM das notas fiscais de fornecedores

select c.NFETIP
       ,c.SERCOD
       ,c.NFECOD
       ,c.NFENUM
       ,c.NFEDATEFE
       ,i.PROCOD
       ,i.NFENCMXML
  into #proncm
  from TBS059 c with (nolock)
 inner join TBS0591 i with (nolock)
    on c.NFETIP=i.NFETIP and c.SERCOD=i.SERCOD and c.NFECOD=i.NFECOD and c.NFENUM=i.NFENUM --and c.NFECAN != 'S' and c.NFEDATEFE != '17530101'
 where c.NFEDATEFE != '17530101'
       and c.NFECAN = 'N'
       and c.NFETIP='N'
       and c.NFECOD not in(select codigo from #fornecedoresGrupo with (nolock))
       and i.NFENCMXML != ''
       and c.NFEDATEFE = (
                           select max(NFEDATEFE)
                             from TBS059 c1 with (nolock)
                            inner join TBS0591 i1 with (nolock)
                               on c1.NFETIP=i1.NFETIP and c1.SERCOD=i1.SERCOD and c1.NFECOD=i1.NFECOD and c1.NFENUM=i1.NFENUM --and c1.NFECAN != 'S' and c1.NFEDATEFE != '17530101'
                            where c1.NFEDATEFE != '17530101'
                                  and c1.NFECAN = 'N'
                                  and c1.NFETIP='N'
                                  and i1.PROCOD = i.PROCOD
                                  and i1.NFENCMXML != ''
                                  and c.NFECOD not in(select codigo from #fornecedoresGrupo with (nolock))
                         )

-- best arts

select c.NFETIP
       ,c.SERCOD
       ,c.NFECOD
       ,c.NFENUM
       ,c.NFEDATEFE
       ,i.PROCOD
       ,i.NFENCMXML
  into #proncm
  from TBS059 c with (nolock)
 inner join TBS0591 i with (nolock)
    on c.NFETIP=i.NFETIP and c.SERCOD=i.SERCOD and c.NFECOD=i.NFECOD and c.NFENUM=i.NFENUM --and c.NFECAN != 'S' and c.NFEDATEFE != '17530101'
 where c.NFEDATEFE != '17530101'
       and c.NFECAN = 'N'
       and c.NFETIP = 'N'
       and i.NFENCMXML != ''
       and c.NFEDATEFE = (
                           select max(NFEDATEFE)
                             from TBS059 c1 with (nolock)
                            inner join TBS0591 i1 with (nolock)
                               on c1.NFETIP=i1.NFETIP and c1.SERCOD=i1.SERCOD and c1.NFECOD=i1.NFECOD and c1.NFENUM=i1.NFENUM --and c1.NFECAN != 'S' and c1.NFEDATEFE != '17530101'
                            where c1.NFEDATEFE != '17530101'
                                  and c1.NFECAN = 'N'
                                  and c1.NFETIP='N'
                                  and i1.PROCOD = i.PROCOD
                                  and i1.NFENCMXML != ''
                                  AND RIGHT(i1.NFECFOP, 3) IN ('102','403','121','202','411')
                         )


--

drop table #ncm_cest

;with UltimoCEST as (
    select 
        c.NFETIP,
        c.SERCOD,
        c.NFECOD,
        c.NFENUM,
        c.NFEDATEFE,
        i.PROCOD,
        i.NFENCMXML,
        i.NFECESTXML,
        row_number() over (
            partition by i.PROCOD
            order by c.NFEDATEFE desc
        ) as rn
    from TBS059 c with (nolock)
    inner join TBS0591 i with (nolock)
        on c.NFETIP=i.NFETIP and c.SERCOD=i.SERCOD 
        and c.NFECOD=i.NFECOD and c.NFENUM=i.NFENUM
    where c.NFEDATEFE <> '17530101'
      and c.NFECAN = 'N'
      and c.NFETIP = 'N'
      and i.NFECESTXML <> ''
      and right(i.NFECFOP, 3) in ('102','403','121','202','411')
      and c.NFECOD not in (
            select codigo from #fornecedoresGrupo with (nolock)
      )
)
select
    NFETIP,
    SERCOD,
    NFECOD,
    NFENUM,
    NFEDATEFE,
    PROCOD,
    NFENCMXML,
    NFECESTXML
into #ncm_cest
from UltimoCEST
where rn = 1;   -- ← só o mais recente por produto

select *
  from #ncm_cest

--

select *
  from #proncm

select p.PROCOD
       ,p.PRODES
       ,p.PROCLAFIS
       ,p.PROCEST
       ,n.NFENCMXML
  from TBS010 p with (nolock)
 inner join #proncm n
    on n.PROCOD=p.PROCOD
 where (p.PROCLAFIS = ''
       or Len(p.PROCLAFIS) < 8)
       and Len(n.NFENCMXML) = 8
 order by p.PROCOD

begin tran
update p
   set p.PROCLAFIS = n.NFENCMXML
  from TBS010 p with (nolock)
 inner join #proncm n
    on n.PROCOD = p.PROCOD
 where (p.PROCLAFIS = ''
       or Len(p.PROCLAFIS) < 8)
       and Len(n.NFENCMXML) = 8

rollback tran
commit tran

-- ncms diferentes entre cadastro do produto e nota fiscal de entrada

select p.PROCOD
       ,n.PROCOD
       ,p.PRODES
       ,p.PROCLAFIS
       ,p.PROCEST
       ,n.NFENCMXML
  from TBS010 p with (nolock)
 inner join #ncm_cest n
         on n.PROCOD = p.PROCOD
 where p.PROCLAFIS <> n.NFENCMXML
 order by p.PROCOD

begin tran
update p
   set p.PROCLAFIS = n.NFENCMXML
  from TBS010 p
 inner join #proncm n
         on n.PROCOD = p.PROCOD
 where rtrim(ltrim(p.PROCLAFIS)) <> rtrim(ltrim(n.NFENCMXML))

rollback tran
commit tran

begin tran

update p
   set p.PROCLAFIS = n.NFENCMXML
  from TBS010 p
 inner join #proncm n
         on rtrim(ltrim(n.PROCOD)) = rtrim(ltrim(p.PROCOD))
 where rtrim(ltrim(p.PROCLAFIS)) collate SQL_Latin1_General_CP1_CI_AS
       <> rtrim(ltrim(n.NFENCMXML)) collate SQL_Latin1_General_CP1_CI_AS;

select @@ROWCOUNT as LinhasAfetadas;

rollback tran

;with UltimoNCM as (
    select n.PROCOD,
           n.NFENCMXML,
           n.NFEDATEFE,
           row_number() over (partition by n.PROCOD order by n.NFEDATEFE desc) as rn
    from #proncm n
)
select p.PROCOD,
       p.PROCLAFIS as CLAFIS_ATUAL,
       u.NFENCMXML as NOVO_NCM,
       u.NFEDATEFE as DATA_NFE
from TBS010 p
inner join UltimoNCM u on u.PROCOD = p.PROCOD and u.rn = 1
where rtrim(ltrim(p.PROCLAFIS)) <> rtrim(ltrim(u.NFENCMXML))
order by p.PROCOD;

;with UltimoNCM as (
    select n.PROCOD,
           n.NFENCMXML,
           n.NFEDATEFE,
           row_number() over (partition by n.PROCOD order by n.NFEDATEFE desc) as rn
    from #proncm n
)
update p
   set p.PROCLAFIS = u.NFENCMXML
  from TBS010 p
  inner join UltimoNCM u
          on u.PROCOD = p.PROCOD
         and u.rn = 1
 where rtrim(ltrim(p.PROCLAFIS)) <> rtrim(ltrim(u.NFENCMXML));

select p.PROCOD, p.PROCLAFIS as CLAFIS_ORIGINAL, n.NFENCMXML as NCMXML_NOVO
from TBS010 p
inner join #proncm n on n.PROCOD = p.PROCOD
where p.PROCLAFIS <> n.NFENCMXML

except

select p.PROCOD, n.NFENCMXML, n.NFENCMXML
from TBS010 p
inner join #proncm n on n.PROCOD = p.PROCOD
where p.PROCLAFIS = n.NFENCMXML;


