-- códigos dos fornecedores do grupo

if object_id('tempdb.dbo.#grupo') is not null
    begin
    	drop table #grupo
    end

create table #grupo (codigo int)

insert into #grupo
exec usp_FornecedoresGrupo 1

select *
  from #grupo


-- NCM do produto conforme nota fiscal do forncedor

if object_id('tempdb.dbo.#ncm_cest_entrada') is not null
    begin
    	drop table #ncm_cest_entrada
    end

select c.NFETIP
       ,c.SERCOD
       ,c.NFECOD
       ,c.NFENUM
       ,c.NFEDATEFE
       ,i.PROCOD
       ,i.NFENCMXML
       ,i.NFECESTXML
  into #ncm_cest_entrada
  from TBS059 c with (nolock)
 inner join TBS0591 i with (nolock)
    on c.NFETIP=i.NFETIP and c.SERCOD=i.SERCOD and c.NFECOD=i.NFECOD and c.NFENUM=i.NFENUM --and c.NFECAN != 'S' and c.NFEDATEFE != '17530101'
 where c.NFEDATEFE != '17530101'
       and c.NFECAN = 'N'
       and c.NFETIP='N'
       --and c.NFECOD not in(select codigo from #grupo with (nolock))   BEST ARTS
       and i.NFENCMXML != ''
       and c.NFEDATEFE = (
                           select max(NFEDATEFE)
                             from TBS059 c1 with (nolock)
                            inner join TBS0591 i1 with (nolock)
                               on c1.NFETIP=i1.NFETIP and c1.SERCOD=i1.SERCOD and c1.NFECOD=i1.NFECOD and c1.NFENUM=i1.NFENUM --and c1.NFECAN != 'S' and c1.NFEDATEFE != '17530101'
                            where c1.NFEDATEFE != '17530101'
                                  and c1.NFECAN = 'N'
                                  and c1.NFETIP = 'N'
                                  and i1.PROCOD = i.PROCOD
                                  and i1.NFENCMXML != ''
                                  --and c.NFECOD not in(select codigo from #grupo with (nolock))  BEST ARTS
                         )

select *
  from #ncm_cest_entrada

-- backup

select PROCOD
       ,PROCLAFIS
       ,PROCEST
  into TBS010_NCM_PROCEST_BKP
  from TBS010 with (nolock)
 where PROCEST <> ''
       or PROCLAFIS <> ''  

-- lista de produtos do cadastro, com NCM vazio ou de tamanho menor do que 8

select p.PROCOD
       ,p.PRODES
       ,p.PROCLAFIS
       ,p.PROCEST
       ,n.NFENCMXML
  from TBS010 p with (nolock)
 inner join #ncm_cest_entrada n
    on n.PROCOD=p.PROCOD
 where (p.PROCLAFIS = ''
       or Len(p.PROCLAFIS) < 8)
       and Len(n.NFENCMXML) = 8
 order by p.PROCOD

-- lista de produtos do cadastro, com NCM diferente do NCM recebido na nota fiscal de entrada

select p.PROCOD
       ,p.PRODES
       ,p.PROCLAFIS
       ,p.PROCEST
       ,n.NFENCMXML
  from TBS010 p with (nolock)
 inner join #ncm_cest_entrada n
    on n.PROCOD=p.PROCOD
 where p.PROCLAFIS <> ''
       and Len(p.PROCLAFIS) = 8
       and p.PROCLAFIS <> n.NFENCMXML
 order by p.PRODES

-- atualiza NCM

begin tran
update p
   set p.PROCLAFIS = n.NFENCMXML
  from TBS010 p with (nolock)
 inner join #ncm_cest_entrada n
    on n.PROCOD = p.PROCOD
 where (p.PROCLAFIS = ''
       or Len(p.PROCLAFIS) < 8)
       and Len(n.NFENCMXML) = 8

rollback tran
commit tran

-- lista produtos com CEST vazios

select p.PROCOD
       ,p.PRODES
       ,p.PROCLAFIS
       ,p.PROCEST
       ,c.NFECESTXML
  from TBS010 p with (nolock)
 inner join #ncm_cest_entrada c
    on c.PROCOD=p.PROCOD
 where p.PROCEST = ''
       and c.NFECESTXML <> '' -- p.PROCLAFIS <> ''
 order by p.PROCOD

begin tran
update p
   set p.PROCEST = c.NFECESTXML
  from TBS010 p with (nolock)
 inner join #ncm_cest_entrada c 
    on c.PROCOD = p.PROCOD
       and p.PROCEST = ''
       and c.NFECESTXML <> ''

rollback tran
commit tran

-- unificar códigos CEST do grupo

if object_id('tempdb.dbo.#cest_grupo') is not null
    begin
    	drop table #cest_grupo
    end

-- tanby matriz
select PROCOD
       ,PROCEST
  into #cest_grupo
  from TBS010 p with (nolock)
 where PROCEST <> ''

union

-- best bag
select PROCOD
       ,PROCEST
  from bb.SIBD2.dbo. TBS010 p with (nolock)
 where PROCEST <> ''

union

-- misaspel
select PROCOD
       ,PROCEST
  from mi.SIBD3.dbo. TBS010 p with (nolock)
 where PROCEST <> ''

union

-- papelyna
select PROCOD
       ,PROCEST
  from pp.SIBD.dbo. TBS010 p with (nolock)
 where PROCEST <> ''

union

-- tanby cd
select PROCOD
       ,PROCEST
  from cd.SIBD.dbo. TBS010 p with (nolock)
 where PROCEST <> ''

union

-- tanby taubaté
select PROCOD collate database_default
       ,PROCEST collate database_default
  from tt.SIBD.dbo. TBS010 p with (nolock)
 where PROCEST <> ''

select *
  into CEST
  from #cest_grupo

begin tran
UPDATE R
   SET R.PROCEST = L.PROCEST
FROM bb.SIBD2.dbo.TBS010 AS R   -- tabela remota (vai ser atualizada)
INNER JOIN TBS010 AS L          -- tabela local (fonte dos dados)
        ON R.PROCOD = L.PROCOD
WHERE (R.PROCEST IS NULL OR R.PROCEST = '');


rollback tran
commit tran

-- correções

select *
  from TBS010 with (nolock)
 where PROCEST = '0000000'

begin tran
update TBS010 
   set PROCEST = ''
 where PROCEST = '0000000'

rollback tran
commit tran

select *
  from TBS010 with (nolock)
 where PROCEST = '9999999'

begin tran
update TBS010 
   set PROCEST = ''
 where PROCEST = '9999999'

rollback tran
commit tran

select PROCEST
  from TBS010 with (nolock)
 where PROCEST <> ''
       and Len(Ltrim(rtrim(PROCEST))) <> 7

begin tran
update TBS010 
   set PROCEST = ''
 where PROCEST <> ''
       and Len(Ltrim(rtrim(PROCEST))) <> 7

rollback tran
commit tran

select PROCOD
       ,PROCEST
  from TBS010 with (nolock)
 where PROCEST <> ''
      and Ltrim(rtrim(PROCEST)) Like '%[^0-9]%'

begin tran
update TBS010 
   set PROCEST = ''
 where PROCEST <> ''
      and Ltrim(rtrim(PROCEST)) Like '%[^0-9]%'

rollback tran
commit tran

-- analises

select *
  from TBS0671 d with (nolock)

select PROCOD
       ,PROCLAFIS
	   ,PROCEST
	   ,PROSTBB
  from TBS010 p with (nolock)
 where p.PROCEST <> ''
       and p.PROSTBB = '60'

select PROCOD
       ,PROCLAFIS
	   ,PROCEST
	   ,PROSTBB
  from TBS010 p with (nolock)
 where p.PROCEST = ''
       and p.PROSTBB = '60'

select PROCOD
       ,PROCLAFIS
	   ,PROCEST
	   ,PROSTBB
  from TBS010 p with (nolock)
 where p.PROCOD = '20968229'

select c.SNESER
       ,*
  from TBS0671 d with (nolock)
 inner join TBS067 c with (nolock)
         on c.SNESER = d.SNESER
		    and c.NFSNUM = d.NFSNUM
			and c.NFSDATEMI >= '20250101'
 where d.PROCOD in(select PROCOD
                     from TBS010 p with (nolock)
                    where p.PROCEST = ''
                          and p.PROSTBB = '60')
 order by c.NFSDATEMI desc

select c.SNESER
       ,*
  from TBS0671 d with (nolock)
 inner join TBS067 c with (nolock)
         on c.SNESER = d.SNESER
		    and c.NFSNUM = d.NFSNUM
			and c.NFSDATEMI >= '20200101'
			and d.NFSCFOP = '6.404'
 order by c.NFSDATEMI desc

-- update geral

select *
  from CEST with (nolock)

select count(*)
  from CEST with (nolock)

begin tran
update p
   set p.PROCEST = c.PROCEST
  from TBS010 p with (nolock)
 inner join CEST c
    on c.PROCOD = p.PROCOD
 where p.PROCEST = ''

rollback tran
commit tran

